  void RefreshSources(){source.Items.Clear();int m=mode.SelectedIndex;selectArea.Enabled=m==0;follow.Enabled=m==0;if(m!=0)follow.Checked=false;camera.Enabled=m!=0;if(m==0)camera.Checked=false;if(m==2){foreach(var w in WindowSources.All())if(w.Handle!=Handle)source.Items.Add(w);}else{foreach(var screen in Screen.AllScreens)source.Items.Add(new SourceChoice{Title=screen.DeviceName+" · "+screen.Bounds.Width+" × "+screen.Bounds.Height,Bounds=screen.Bounds});}source.Enabled=m==1||m==2;source.Visible=m==1||m==2;selectArea.Visible=m==0;if(source.Items.Count>0)source.SelectedIndex=0;}
  Rectangle BoundsForMode(){if(mode.SelectedIndex==0)return region;if(mode.SelectedIndex==3)return SystemInformation.VirtualScreen;var choice=source.SelectedItem as SourceChoice;if(choice==null)return Rectangle.Empty;if(mode.SelectedIndex==2)return WindowSources.Bounds(choice.Handle);return choice.Bounds;}
  void UpdateInfo(){Rectangle bounds=BoundsForMode();sourceInfo.Text=bounds.IsEmpty?"Selecione a região ou janela para começar.":bounds.Width+" × "+bounds.Height+" px · "+(follow.Checked?"acompanha o mouse":mode.SelectedItem.ToString());if(mode.SelectedIndex==2)sourceInfo.Text+=" · Janela visível: sobreposições aparecem; não minimize.";preview.SourceSize=bounds.IsEmpty?new Size(1920,1080):bounds.Size;preview.Caption=mode.SelectedItem==null?"Selecionar fonte":mode.SelectedItem.ToString();preview.Invalidate();bool allow=mode.SelectedIndex!=0;camera.Enabled=allow;cameras.Enabled=allow;cameraSize.Enabled=allow;if(record!=null)record.Enabled=!ActiveRecording&&bounds.Width>=2&&bounds.Height>=2;}
  async Task StartRecording(){if(engine.IsRecording||starting)return;starting=true;cancelStart=false;try{var bounds=BoundsForMode();if(bounds.Width<2||bounds.Height<2)throw new Exception("Selecione uma área ou fonte válida.");string ff=EncoderLocator.Find();if(ff==null)throw new Exception("FFmpeg não encontrado. Use a pasta completa do Priint com a subpasta tools.");var choice=source.SelectedItem as SourceChoice;if(camera.Checked){await StartCamera();if(cancelStart)throw new OperationCanceledException("Gravação cancelada.");if(cameraFeed==null||!cameraFeed.IsReady)throw new Exception("Ative a prévia da câmera e confira o dispositivo antes de gravar.");}var req=new RecordingRequest{Mode=(RecordingMode)mode.SelectedIndex,Region=bounds,WindowHandle=choice==null?IntPtr.Zero:choice.Handle,OutputDirectory=folder.Text,Fps=(int)fps.Value,CaptureCursor=cursor.Checked,FollowMouse=follow.Checked,FollowSize=bounds.Size,EncoderPath=ff,UseNvenc=((EncoderChoice)encoder.SelectedItem).Index>=0,SystemAudio=!Testing&&(av.AudioMode==1||av.AudioMode==3),Microphone=!Testing&&(av.AudioMode==2||av.AudioMode==3),OutputDeviceId=av.OutputDevice,MicrophoneId=av.MicrophoneDevice,CameraShape=av.CameraShape,CameraZoom=av.CameraZoom,CameraMirror=av.CameraMirror,CameraTracking=av.CameraTracking};av.VideoFps=(int)fps.Value;av.VideoGpu=((EncoderChoice)encoder.SelectedItem).Index;av.VideoNvenc=av.VideoGpu>=0;VideoProfiles.Apply(av,req);if(req.Microphone)DeviceAccess.Check(false);if(camera.Checked){if(mode.SelectedIndex==0)throw new Exception("Câmera apenas em monitor, janela ou desktop completo.");if(cameras.SelectedItem==null)throw new Exception("Atualize a lista e escolha sua câmera.");req.CameraDevice=cameras.SelectedItem.ToString();req.Camera=cameraFeed;req.CameraBounds=preview.OutputCameraBounds(bounds.Size);}
   record.Enabled=false;mode.Enabled=false;fps.Enabled=false;encoder.Enabled=false;source.Enabled=false;preview.Enabled=false;camera.Enabled=false;cameras.Enabled=false;starting=true;Hide();await Task.Delay(220);if(cancelStart)throw new OperationCanceledException("Gravação cancelada.");if(!Testing){if(hud!=null)hud.Dispose();hud=new RecordingHud();await hud.Countdown();}if(cancelStart)throw new OperationCanceledException("Gravação cancelada.");await Task.Run(()=>engine.Start(req));if(cancelStart){await engine.StopAsync();throw new OperationCanceledException("Gravação cancelada.");}await engine.Ready;starting=false;if(hud!=null)hud.State("Gravando");PointF placement=preview.Position;av.CameraX=placement.X;av.CameraY=placement.Y;var remembered=Preferences.Load();CopyAv(av,remembered);remembered.VideoFps=req.Fps;remembered.VideoNvenc=req.UseNvenc;remembered.VideoCursor=req.CaptureCursor;remembered.VideoFolder=req.OutputDirectory;if(!Testing)try{remembered.Save();}catch{}stop.Enabled=true;status.Text="● Gravando · parar: "+Preferences.KeyLabel(av.StopKey);
