  void ShowStoppedHud(bool completed=false){if(hud==null)return;var ended=hud;ended.State(completed?"Gravação concluída":"Parado");var delay=new Timer{Interval=3200};delay.Tick+=delegate{delay.Dispose();if(!ended.IsDisposed)ended.Dispose();if(object.ReferenceEquals(hud,ended))hud=null;};delay.Start();}
  public Task StopRecording(){if(stopWork!=null&&!stopWork.IsCompleted)return stopWork;stopWork=StopCore();return stopWork;}
  async Task StopCore(){
   if(starting&&!engine.IsRecording){cancelStart=true;if(hud!=null)hud.Cancel();status.Text="Cancelando a preparação…";return;}
   if(stopping)return;stopping=true;if(hud!=null)hud.Hide();stop.Enabled=false;status.Text="Finalizando e verificando o vídeo…";string saved=null;
   try{saved=await engine.StopAsync();status.Text="Gravação concluída · "+engine.EffectiveFps.ToString("F1")+" capturas/s"+(engine.PerformanceLimited?" · abaixo do alvo; reduza FPS/resolução ou use GPU":"");RefreshLibrary();}
   catch(Exception ex){status.Text="Não concluído: "+ex.Message;}
   finally{stopping=false;preview.Enabled=true;mode.Enabled=true;fps.Enabled=true;encoder.Enabled=true;source.Enabled=mode.SelectedIndex==1||mode.SelectedIndex==2;UpdateInfo();ShowStoppedHud(saved!=null);Show();WindowState=FormWindowState.Normal;}
   if(saved!=null&&!Testing)OpenLibrary(saved);
  }
  void OpenLibrary(string selected){using(var libraryWindow=new RecordingLibraryForm(folder.Text,selected))libraryWindow.ShowDialog(this);}
  void RefreshLibrary(){library.Items.Clear();try{if(Directory.Exists(folder.Text)){var files=Array.FindAll(new DirectoryInfo(folder.Text).GetFiles(),f=>f.Extension.Equals(".mp4",StringComparison.OrdinalIgnoreCase)||f.Extension.Equals(".avi",StringComparison.OrdinalIgnoreCase));Array.Sort(files,(a,b)=>b.LastWriteTime.CompareTo(a.LastWriteTime));foreach(var f in files)if(!f.Name.Contains(".partial"))library.Items.Add(f.Name);}}catch(Exception ex){if(status!=null)status.Text="Não foi possível listar a pasta: "+ex.Message;}}
  void OpenFolder(){try{Directory.CreateDirectory(folder.Text);Process.Start(new ProcessStartInfo(folder.Text){UseShellExecute=true});}catch(Exception ex){status.Text=ex.Message;}}
  static List<string> FindCameras(){string ff=EncoderLocator.Find();if(ff==null)throw new Exception("FFmpeg não encontrado.");var names=new List<string>();using(var p=new Process{StartInfo=new ProcessStartInfo(ff,"-hide_banner -list_devices true -f dshow -i dummy"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true}}){p.Start();var output=p.StandardError.ReadToEndAsync();if(!p.WaitForExit(10000)){p.Kill();throw new Exception("Consulta de câmeras expirou.");}foreach(Match m in Regex.Matches(output.Result,"\"([^\"]+)\" \\(video\\)"))names.Add(m.Groups[1].Value);}return names;}
  public static void RunUiTests(){UiRegression.Run();}
