  public bool CameraVisible;public float CameraFraction=.24f;public PointF Position=new PointF(.72f,.68f);public Size SourceSize=new Size(1920,1080),CameraPixels=Size.Empty;public string Caption="Área selecionada",Shape="Retangular";public float Zoom=1;public bool Mirror,Track;public CameraFeed Feed;public Action<PointF,Size> PlacementChanged;Timer cameraRefresh=new Timer{Interval=16};long paintedFrame=-1;Bitmap screen;bool dragging,resizing;Point last;
  public CameraPreview(){DoubleBuffered=true;BackColor=Color.FromArgb(14,17,18);cameraRefresh.Tick+=delegate{if(Visible&&CameraVisible&&Feed!=null&&Feed.FramesReceived!=paintedFrame){paintedFrame=Feed.FramesReceived;var dirty=CameraRect();dirty.Inflate(4,4);Invalidate(dirty);}};cameraRefresh.Start();}
  public void Screen(Bitmap b){if(screen!=null)screen.Dispose();screen=b;Invalidate();}
  Rectangle FrameRect(){float scale=Math.Min((float)Width/Math.Max(1,SourceSize.Width),(float)Height/Math.Max(1,SourceSize.Height));int w=(int)(SourceSize.Width*scale),h=(int)(SourceSize.Height*scale);return new Rectangle((Width-w)/2,(Height-h)/2,w,h);}
  Size Box(Size size){int w=CameraPixels.IsEmpty?(int)(size.Width*CameraFraction):CameraPixels.Width;int h=CameraPixels.IsEmpty?w*3/4:CameraPixels.Height;if(Shape!="Retangular")h=w;float scale=Math.Min(1,Math.Min((float)size.Width/Math.Max(1,w),(float)size.Height/Math.Max(1,h)));return new Size(Math.Max(2,(int)(w*scale))&~1,Math.Max(2,(int)(h*scale))&~1);}
  Rectangle CameraRect(){var frame=FrameRect();var b=OutputCameraBounds(SourceSize);return new Rectangle(frame.X+(int)((float)b.X/SourceSize.Width*frame.Width),frame.Y+(int)((float)b.Y/SourceSize.Height*frame.Height),Math.Max(2,(int)((float)b.Width/SourceSize.Width*frame.Width)),Math.Max(2,(int)((float)b.Height/SourceSize.Height*frame.Height)));}
  public void ClampCamera(){var box=Box(SourceSize);Position=new PointF(Math.Max(0,Math.Min(Position.X,1f-(float)box.Width/Math.Max(1,SourceSize.Width))),Math.Max(0,Math.Min(Position.Y,1f-(float)box.Height/Math.Max(1,SourceSize.Height))));}
  public Rectangle OutputCameraBounds(Size size){var b=Box(size);Position=new PointF(Math.Max(0,Math.Min(Position.X,1f-(float)b.Width/size.Width)),Math.Max(0,Math.Min(Position.Y,1f-(float)b.Height/size.Height)));return new Rectangle(((int)(Position.X*size.Width))&~1,((int)(Position.Y*size.Height))&~1,b.Width,b.Height);}
  protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;using(var background=new SolidBrush(BackColor))g.FillRectangle(background,e.ClipRectangle);var frame=FrameRect();if(screen!=null)g.DrawImage(screen,frame);else{using(var p=new Pen(Color.FromArgb(30,36,32))){for(int x=0;x<Width;x+=32)g.DrawLine(p,x,0,x,Height);for(int y=0;y<Height;y+=32)g.DrawLine(p,0,y,Width,y);}g.DrawString(Caption,Font,Brushes.White,24,28);}using(var pen=new Pen(Brand.Lime,1))g.DrawRectangle(pen,frame);if(CameraVisible){ClampCamera();var r=CameraRect();{if(Feed==null||!Feed.DrawLatest(g,r,Shape,Zoom,Mirror,Track)){using(var b=new SolidBrush(Color.FromArgb(55,70,46)))g.FillRectangle(b,r);g.DrawString("CÂMERA\nativar prévia",Font,Brushes.White,r.X+8,r.Y+8);}}using(var p=new Pen(Brand.Lime,2)){if(Shape=="Redonda")g.DrawEllipse(p,r);else g.DrawRectangle(p,r);}g.FillRectangle(Brushes.White,r.Right-6,r.Bottom-6,7,7);}}
  protected override void OnMouseDown(MouseEventArgs e){if(CameraVisible&&CameraRect().Contains(e.Location)){var r=CameraRect();resizing=e.X>r.Right-12&&e.Y>r.Bottom-12;dragging=true;last=e.Location;Capture=true;}}
  protected override void OnMouseMove(MouseEventArgs e){if(dragging){var frame=FrameRect();if(resizing){var b=Box(SourceSize);CameraPixels=new Size(Math.Max(32,b.Width+(int)((float)(e.X-last.X)/frame.Width*SourceSize.Width)),Math.Max(32,b.Height+(int)((float)(e.Y-last.Y)/frame.Height*SourceSize.Height)));}else Position=new PointF(Position.X+(float)(e.X-last.X)/Math.Max(1,frame.Width),Position.Y+(float)(e.Y-last.Y)/Math.Max(1,frame.Height));last=e.Location;ClampCamera();Invalidate();}}
