 } class RegionPicker:Form {
  Point start;Rectangle selected;bool dragging;Bitmap desktop;public Rectangle Selected{get{var r=selected;r.Offset(Left,Top);return r;}}
  public RegionPicker(){FormBorderStyle=FormBorderStyle.None;StartPosition=FormStartPosition.Manual;AutoScaleMode=AutoScaleMode.None;Bounds=SystemInformation.VirtualScreen;TopMost=true;DoubleBuffered=true;KeyPreview=true;Cursor=Cursors.Cross;desktop=new Bitmap(Width,Height);using(var g=Graphics.FromImage(desktop))g.CopyFromScreen(Left,Top,0,0,Size);}
  protected override void OnPaint(PaintEventArgs e){e.Graphics.DrawImageUnscaled(desktop,0,0);using(var b=new SolidBrush(Color.FromArgb(65,0,0,0)))e.Graphics.FillRectangle(b,ClientRectangle);if(selected.Width>0){e.Graphics.SetClip(selected);e.Graphics.DrawImageUnscaled(desktop,0,0);e.Graphics.ResetClip();using(var p=new Pen(Brand.Lime,2))e.Graphics.DrawRectangle(p,selected);}e.Graphics.DrawString("Arraste a área do vídeo · Esc cancela",SystemFonts.MessageBoxFont,Brushes.White,24,24);}
  protected override void OnMouseDown(MouseEventArgs e){if(e.Button!=MouseButtons.Left)return;start=e.Location;dragging=true;Capture=true;}
  protected override void OnMouseMove(MouseEventArgs e){if(dragging){selected=Rectangle.Intersect(Rectangle.FromLTRB(Math.Min(start.X,e.X),Math.Min(start.Y,e.Y),Math.Max(start.X,e.X),Math.Max(start.Y,e.Y)),ClientRectangle);Invalidate();}}
  protected override void OnMouseUp(MouseEventArgs e){OnMouseMove(e);dragging=false;Capture=false;if(selected.Width>=16&&selected.Height>=16){DialogResult=DialogResult.OK;Close();}}
  protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Escape){DialogResult=DialogResult.Cancel;Close();}}
  protected override void Dispose(bool d){if(d&&desktop!=null)desktop.Dispose();base.Dispose(d);}
 }
 static class WindowSources {
  delegate bool EnumProc(IntPtr h,IntPtr p);[DllImport("user32.dll")]static extern bool EnumWindows(EnumProc p,IntPtr l);[DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr h);[DllImport("user32.dll")]static extern bool IsIconic(IntPtr h);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetWindowText(IntPtr h,StringBuilder b,int n);[DllImport("user32.dll")]static extern bool GetWindowRect(IntPtr h,out RECT r);struct RECT{public int L,T,R,B;}
  public static Rectangle Bounds(IntPtr h){RECT r;if(h==IntPtr.Zero||!GetWindowRect(h,out r)||IsIconic(h))return Rectangle.Empty;return Rectangle.FromLTRB(r.L,r.T,r.R,r.B);}
  public static List<SourceChoice> All(){var list=new List<SourceChoice>();EnumWindows(delegate(IntPtr h,IntPtr p){if(IsWindowVisible(h)&&!IsIconic(h)){var b=new StringBuilder(256);GetWindowText(h,b,256);var r=Bounds(h);if(b.Length>0&&r.Width>20&&r.Height>20)list.Add(new SourceChoice{Title=b.ToString(),Handle=h,Bounds=r});}return true;},IntPtr.Zero);return list;}
 }
 static class EncoderLocator {
  public static string Find(){string local=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"tools","ffmpeg.exe");if(File.Exists(local))return local;foreach(var part in (Environment.GetEnvironmentVariable("PATH")??"").Split(';')){try{var p=Path.Combine(part.Trim('"'),"ffmpeg.exe");if(File.Exists(p))return p;}catch{}}string winget=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Microsoft","WinGet","Packages");if(Directory.Exists(winget))foreach(var root in Directory.GetDirectories(winget,"Gyan.FFmpeg_*"))foreach(var version in Directory.GetDirectories(root)){string p=Path.Combine(version,"bin","ffmpeg.exe");if(File.Exists(p))return p;}return null;}
 }
}
