 class DarkChoice:Button {
  public System.Collections.Generic.List<object> Items=new System.Collections.Generic.List<object>();int selected=-1;public event EventHandler SelectedIndexChanged;public ComboBoxStyle DropDownStyle{get;set;}
  public int SelectedIndex{get{return selected;}set{selected=value;Text=(SelectedItem==null?"Selecionar…":SelectedItem.ToString())+"  ▾";if(SelectedIndexChanged!=null)SelectedIndexChanged(this,EventArgs.Empty);}}
  public object SelectedItem{get{return selected>=0&&selected<Items.Count?Items[selected]:null;}set{SelectedIndex=Items.IndexOf(value);}}
  public DarkChoice(){FlatStyle=FlatStyle.Flat;BackColor=Brand.Back;ForeColor=Brand.Ink;FlatAppearance.BorderColor=Color.FromArgb(63,72,65);TextAlign=ContentAlignment.MiddleLeft;AutoEllipsis=true;Height=30;Cursor=Cursors.Hand;}
  protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Brand.Back);using(var border=new Pen(Color.FromArgb(63,72,65)))e.Graphics.DrawRectangle(border,0,0,Width-1,Height-1);TextRenderer.DrawText(e.Graphics,Text,Font,new Rectangle(6,2,Width-12,Height-4),Enabled?Brand.Ink:Brand.Muted,TextFormatFlags.Left|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}
  ContextMenuStrip dropdown;
  public ContextMenuStrip ActiveMenu{get{return dropdown;}}
  protected override void OnClick(EventArgs e){base.OnClick(e);if(dropdown==null){dropdown=new ContextMenuStrip{ShowImageMargin=false,BackColor=Brand.Panel,ForeColor=Brand.Ink,Renderer=new ToolStripProfessionalRenderer(new PriintMenuColors())};}if(dropdown.Visible){dropdown.Close();return;}while(dropdown.Items.Count>0){var old=dropdown.Items[0];dropdown.Items.RemoveAt(0);old.Dispose();}for(int i=0;i<Items.Count;i++){int index=i;var item=dropdown.Items.Add(Items[i].ToString());item.Click+=delegate{SelectedIndex=index;};}if(dropdown.Items.Count==0)dropdown.Items.Add("Nenhum item disponível").Enabled=false;dropdown.Show(this,new Point(0,Height));}
