 static class RecordingTrayIcon {
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern bool DestroyIcon(IntPtr h);
  public static Icon Create(bool paused=false){using(var original=Brand.AppIcon())using(var bitmap=original.ToBitmap()){using(var g=Graphics.FromImage(bitmap)){g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;g.FillEllipse(Brushes.Black,17,17,15,15);using(var dot=new SolidBrush(paused?Color.Gold:Brand.Lime))g.FillEllipse(dot,19,19,11,11);}IntPtr h=bitmap.GetHicon();try{using(var borrowed=Icon.FromHandle(h))return (Icon)borrowed.Clone();}finally{DestroyIcon(h);}}}
 }
